ruleToc.chapterUrl:
html<js>
r=result
try{
	rr=r.match(/= ?"([^"]+)"/g);
	for(i in rr){
	 a=rr[i].match(/"(.*)"/)[1]
	 if(/L2Jv/.test(a)){
	 		 	href=java.base64Decode(a)
	 	}else if(/html/.test(a)){href=a}
	}
if(href==""){
		href=java.getString("a@href")
		}
href
}catch{
	java.getString("href")
}
</js>

