ruleToc.chapterList:
@js:
let v = [],
		list = [];
JSON.parse(result).list.map($=>{

//分卷判定
		V = $.name;
		if(v[v.length-1]!=V&&!/^\s*$/.test(V)){
				v.push(V)
				list.push({
						name: '📖['+V+']📖',
						volume: true
					})
			}

$.bookChapters.map($=>{
		return list.push({
				name: $.name,
				url: `https://readbook-service-freebook.cread.com/cx/itf/chapterRead?bookId=${$.bookid}&chapterId=${$.id}`,
				info: `章节字数：${$.wordCount}　更新时间：${$.updateDate}`
			});
	});
});
v.length<2?list.filter($=>!$.volume):list

ruleContent.content:
$.url@js:
let content=""
if(result){
let b64 = java.ajax(result)
let str=java.base64Decode(b64.match(/'(.+?)'/)[1])
let list=JSON.parse(str).p
for (i =0;i<list.length;i++){
content+= list[i]+"\n"
}
}else{
content+="购买后继续阅读本章内容"
}
content

