ruleToc.chapterList:
@css:
div.chapterbox > table > tbody > tr,
div.chapterbox > table > tbody > tr > td,
div.chapterbox > div.vol_name
@js:
list = [];
$ = result;
for (i in $) {
    if (/vol_name/.test(String($[i]))) {
        text = "🏮 ↓ 〖" + String($[i].text()) + "〗 ↓ 🏮";
        list.push({
            text: text,
            volume: true
        });
    } else {  
        $[i].select("td").forEach(a => {     
            vip = /a/.test(a.select("i"));
            text = a.select("a").text();
            href = a.select("a").attr("href");
            if (vip) {
                symbol = "💎";
            } else {
                symbol = "💮";
            }
            title = symbol + "〖" + text + "〗" + symbol;
            url = `${href},{"webView":true}`
            list.push({   
                title: title,
                isVip: vip,
                url: url
            });
        });
    }
}
list

ruleToc.nextTocUrl:
@js:
var n=(JSON.parse(result).data.chapter.chapterCount)/50+1;
var list=[];
baseUrl=baseUrl.replace(/1&order=asc&site=/,'');
for(var i=2;i<n;i++){
var url=baseUrl+i+'&order=asc&site=';
list.push(url);
}
list;

